"use strict";

/**
 * Callbacks invoked while walking the HTML token stream. Every callback is
 * optional and, when present, must return the new parse position so the walker
 * can continue from there.
 * @typedef {object} HtmlTokenCallbacks
 * @property {((input: string, start: number, end: number, nameStart: number, nameEnd: number, selfClosing: boolean) => number)=} openTag called for each open tag, spanning the complete tag
 * @property {((input: string, start: number, end: number, nameStart: number, nameEnd: number) => number)=} closeTag called for each close tag, spanning the complete tag
 * @property {((input: string, nameStart: number, nameEnd: number, valueStart: number, valueEnd: number, quoteType: number) => number)=} attribute called before `openTag` for each attribute
 * @property {((input: string, start: number, end: number) => number)=} comment called for each HTML comment, spanning the complete comment
 * @property {((input: string, start: number, end: number) => number)=} text called for text content between tags
 */

// Character codes used by the tokenizer.
const CC_TAB = "\t".charCodeAt(0);
const CC_LINE_FEED = "\n".charCodeAt(0);
const CC_FORM_FEED = "\f".charCodeAt(0);
const CC_CARRIAGE_RETURN = "\r".charCodeAt(0);
const CC_SPACE = " ".charCodeAt(0);

const CC_LESS_THAN = "<".charCodeAt(0);
const CC_GREATER_THAN = ">".charCodeAt(0);
const CC_SOLIDUS = "/".charCodeAt(0);
const CC_EXCLAMATION_MARK = "!".charCodeAt(0);
const CC_HYPHEN_MINUS = "-".charCodeAt(0);
const CC_EQUALS_SIGN = "=".charCodeAt(0);
const CC_QUOTATION_MARK = '"'.charCodeAt(0);
const CC_APOSTROPHE = "'".charCodeAt(0);

const CC_UPPER_A = "A".charCodeAt(0);
const CC_UPPER_Z = "Z".charCodeAt(0);
const CC_LOWER_A = "a".charCodeAt(0);
const CC_LOWER_Z = "z".charCodeAt(0);

/** Unquoted attribute value. */
const QUOTE_NONE = 0;
/** Double-quoted attribute value. */
const QUOTE_DOUBLE = 1;
/** Single-quoted attribute value. */
const QUOTE_SINGLE = 2;

/**
 * @param {number} cc character code
 * @returns {boolean} true when the character is ASCII whitespace
 */
const isWhitespace = (cc) =>
	cc === CC_SPACE ||
	cc === CC_TAB ||
	cc === CC_LINE_FEED ||
	cc === CC_CARRIAGE_RETURN ||
	cc === CC_FORM_FEED;

/**
 * @param {number} cc character code
 * @returns {boolean} true when the character is an ASCII letter
 */
const isASCIIAlpha = (cc) =>
	(cc >= CC_UPPER_A && cc <= CC_UPPER_Z) ||
	(cc >= CC_LOWER_A && cc <= CC_LOWER_Z);

/**
 * A tag name character is anything that isn't whitespace and isn't one of the
 * characters that terminate the name (`/` or `>`).
 * @param {number} cc character code
 * @returns {boolean} true when the character can be part of a tag name
 */
const isTagNameChar = (cc) =>
	!Number.isNaN(cc) &&
	!isWhitespace(cc) &&
	cc !== CC_SOLIDUS &&
	cc !== CC_GREATER_THAN;

/**
 * An attribute name character is anything that isn't whitespace and isn't one
 * of the characters that terminate the name.
 * @param {number} cc character code
